begin;
select pg_advisory_xact_lock(84746007);

do $$ begin
  if to_regclass('public.hsd_factory_requests') is null then
    raise exception 'HomeService Catalogue-to-Mission Rescue baseline is required before Category Master Experience.';
  end if;
end $$;

alter table public.hsd_factory_requests
  add column if not exists blueprint_code text,
  add column if not exists blueprint_version integer,
  add column if not exists preset_code text,
  add column if not exists structured_configuration jsonb not null default '{}'::jsonb;

alter table public.hsd_factory_scenarios
  add column if not exists blueprint_code text,
  add column if not exists blueprint_version integer,
  add column if not exists preset_code text,
  add column if not exists configuration_snapshot jsonb not null default '{}'::jsonb;

alter table public.hsd_factory_sellables
  add column if not exists blueprint_code text,
  add column if not exists blueprint_version integer,
  add column if not exists preset_code text;

create table if not exists public.hsd_category_experience_blueprints(
  id uuid primary key default gen_random_uuid(), tenant_id text not null default 'angelcare-main', category_id uuid not null references public.hsd_service_categories(id) on delete cascade,
  code text not null, concept text not null, title_fr text not null, subtitle_fr text not null default '', hero_statement_fr text not null default '', accent text not null default 'blue', icon text not null default 'Sparkles', audience text not null default 'both', version_number integer not null default 1,
  zero_typing_promise_fr text not null default '', ai_composition_profile jsonb not null default '{}'::jsonb, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(tenant_id,category_id,version_number), unique(tenant_id,code)
);
create table if not exists public.hsd_category_experience_sections(
  id uuid primary key default gen_random_uuid(), tenant_id text not null default 'angelcare-main', blueprint_id uuid not null references public.hsd_category_experience_blueprints(id) on delete cascade,
  code text not null, title_fr text not null, description_fr text not null default '', layout text not null default 'cards', sort_order integer not null default 100, status text not null default 'active', unique(tenant_id,blueprint_id,code)
);
create table if not exists public.hsd_category_experience_fields(
  id uuid primary key default gen_random_uuid(), tenant_id text not null default 'angelcare-main', section_id uuid not null references public.hsd_category_experience_sections(id) on delete cascade,
  code text not null, label_fr text not null, description_fr text not null default '', field_type text not null, required boolean not null default false, default_value jsonb, min_value numeric, max_value numeric, unit text, semantic text, sort_order integer not null default 100, status text not null default 'active', unique(tenant_id,section_id,code)
);
create table if not exists public.hsd_category_experience_options(
  id uuid primary key default gen_random_uuid(), tenant_id text not null default 'angelcare-main', field_id uuid not null references public.hsd_category_experience_fields(id) on delete cascade,
  code text not null, label_fr text not null, description_fr text not null default '', sort_order integer not null default 100, status text not null default 'active', unique(tenant_id,field_id,code)
);
create table if not exists public.hsd_category_experience_presets(
  id uuid primary key default gen_random_uuid(), tenant_id text not null default 'angelcare-main', blueprint_id uuid not null references public.hsd_category_experience_blueprints(id) on delete cascade,
  code text not null, name_fr text not null, description_fr text not null default '', badge_fr text not null default '', mode text not null, universe text not null, field_values jsonb not null default '{}'::jsonb,
  default_start_time time not null default '08:00', default_end_time time not null default '16:00', default_day_count integer not null default 1, scenario_count integer not null default 3, max_activities_per_day integer not null default 6, max_options integer not null default 4,
  sort_order integer not null default 100, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,blueprint_id,code)
);
create table if not exists public.hsd_category_experience_usage(
  id uuid primary key default gen_random_uuid(), tenant_id text not null default 'angelcare-main', category_id uuid not null references public.hsd_service_categories(id) on delete cascade,
  blueprint_code text not null, preset_code text, factory_request_id uuid references public.hsd_factory_requests(id) on delete set null, configuration_snapshot jsonb not null default '{}'::jsonb, created_by text, created_at timestamptz not null default now()
);

create index if not exists idx_hsd_category_experience_blueprints_category on public.hsd_category_experience_blueprints(tenant_id,category_id,status);
create index if not exists idx_hsd_category_experience_presets_blueprint on public.hsd_category_experience_presets(tenant_id,blueprint_id,status,sort_order);
create index if not exists idx_hsd_category_experience_usage_category on public.hsd_category_experience_usage(tenant_id,category_id,created_at desc);

alter table public.hsd_category_experience_blueprints enable row level security;
alter table public.hsd_category_experience_sections enable row level security;
alter table public.hsd_category_experience_fields enable row level security;
alter table public.hsd_category_experience_options enable row level security;
alter table public.hsd_category_experience_presets enable row level security;
alter table public.hsd_category_experience_usage enable row level security;

do $$
declare t text;
begin
  foreach t in array array['hsd_category_experience_blueprints','hsd_category_experience_sections','hsd_category_experience_fields','hsd_category_experience_options','hsd_category_experience_presets','hsd_category_experience_usage'] loop
    execute format('drop policy if exists %I on public.%I', t||'_tenant_read', t);
    execute format('create policy %I on public.%I for select using (tenant_id = ''angelcare-main'')', t||'_tenant_read', t);
  end loop;
end $$;

with c as (select id from public.hsd_service_categories where tenant_id='angelcare-main' and code='HS-CHILD-HOME'),
b as (
 insert into public.hsd_category_experience_blueprints(tenant_id,category_id,code,concept,title_fr,subtitle_fr,hero_statement_fr,accent,icon,audience,version_number,zero_typing_promise_fr,ai_composition_profile,status)
 select 'angelcare-main',c.id,'EXP-HS-CHILD-HOME','family_care','Garde d’enfant à domicile','Une expérience de garde pensée autour du rythme familial, de la sécurité et de l’épanouissement.','Garde d’enfant à domicile : choisissez un scénario complet, ajustez uniquement les sélections utiles, puis renseignez les dates et horaires.','rose','HeartHandshake','b2c',1,'Aucun texte narratif obligatoire. Le scénario pré-remplit le dossier; seules les dates et heures restent à préciser.','{"purpose":"Composer des missions Garde d’enfant à domicile exclusivement depuis les activités locales et cette configuration structurée.","forbidden":["inventer une activité","inventer un prix","modifier les dates","ignorer les contrôles de sécurité","faire une promesse médicale"],"priorities":["cohérence du scénario","respect du rythme","usage des IDs locaux","variation utile des propositions","explication concise"]}'::jsonb,'active' from c
 on conflict(tenant_id,category_id,version_number) do update set concept=excluded.concept,title_fr=excluded.title_fr,subtitle_fr=excluded.subtitle_fr,hero_statement_fr=excluded.hero_statement_fr,accent=excluded.accent,icon=excluded.icon,audience=excluded.audience,zero_typing_promise_fr=excluded.zero_typing_promise_fr,ai_composition_profile=excluded.ai_composition_profile,status='active',updated_at=now()
 returning id
)
select 1;

with b as (select id from public.hsd_category_experience_blueprints where tenant_id='angelcare-main' and code='EXP-HS-CHILD-HOME'),
s as (
 insert into public.hsd_category_experience_sections(tenant_id,blueprint_id,code,title_fr,description_fr,layout,sort_order,status)
 select 'angelcare-main',b.id,'beneficiary','Profil enfant','Choisissez le profil sans rédiger de description.','profile',100,'active' from b
 on conflict(tenant_id,blueprint_id,code) do update set title_fr=excluded.title_fr,description_fr=excluded.description_fr,layout=excluded.layout,sort_order=excluded.sort_order,status='active'
 returning id
)
select 1;

